const LABEL_TIPO={abertura_matricula:'Abertura de Matrícula',compra_e_venda:'Compra e Venda',alienacao_fiduciaria:'Alienação Fiduciária',adjudicacao:'Adjudicação',arrematacao:'Arrematação',partilha:'Partilha',doacao:'Doação',heranca:'Herança',hipoteca:'Hipoteca',penhora:'Penhora',arresto:'Arresto',usufruto:'Usufruto',cancelamento:'Cancelamento',cancelamento_onus:'Cancelamento de Ônus',retificacao:'Retificação',destacamento:'Destacamento',averbacao:'Averbação',averbacao_construcao:'Averbação de Construção',registro:'Registro',transporte_onus:'Transporte de Ônus',transporte_onus_hipoteca:'Transporte de Hipoteca',transporte_onus_penhora:'Transporte de Penhora',transporte_onus_arresto:'Transporte de Arresto',permuta:'Permuta',cessao_direitos:'Cessão de Direitos',compromisso_venda_compra:'Compromisso de Venda e Compra',servidao:'Servidão',indisponibilidade:'Indisponibilidade',cancelamento_indisponibilidade:'Cancelamento de Indisponibilidade',dacao_pagamento:'Dação em Pagamento',integralizacao:'Integralização de Capital',sobrepartilha:'Sobrepartilha',alteracao_denominacao:'Alteração de Denominação',clausula_restritiva:'Cláusulas Restritivas'};
