  {re:'solicitad[oa]\\s+por[^\\n]{0,160}?\\bdata\\s*:?\\s*'+P_DATA,fonte:'rodapé ONR',confianca:'alta',semRuido:true},
  {re:'(?:data\\s+d[ae]\\s+(?:emiss[ãa]o|expedi[çc][ãa]o|impress[ãa]o)|emiss[ãa]o|expedi[çc][ãa]o)\\s*:?\\s*'+P_DATA,fonte:'rótulo de emissão',confianca:'alta'},
  {re:'(?:certid[ãa]o|documento|c[óo]pia)[^.\\n]{0,60}?(?:emitid|expedid|extra[íi]d|impress|fornecid|lavrad)\\w*\\s*(?:eletronicamente\\s*)?(?:em|no\\s+dia|aos?)\\s*:?\\s*'+P_DATA,fonte:'certidão emitida em',confianca:'alta'},
  {re:'(?:emitid[ao]|expedid[ao]|impress[ao]|extra[íi]d[ao])\\s*(?:eletronicamente\\s*)?(?:em|no\\s+dia|aos?)\\s*:?\\s*'+P_DATA,fonte:'emitida em',confianca:'media'},
  {re:'v[áa]lid[ao]\\s+por\\s+\\d{1,3}\\s+dias?[^.\\n]{0,60}?(?:a\\s+(?:partir|contar)\\s+de|desde)\\s*'+P_DATA,fonte:'prazo de validade',confianca:'media'},
  {re:'(?:CERTIFICO|certifico|nada\\s+mais\\s+consta|o\\s+ato\\s+acima)[\\s\\S]{0,800}?[A-ZÀ-Ü][A-Za-zÀ-ÿ\\s.\'-]{2,40},\\s*(?:aos?\\s+)?'+P_DATA,fonte:'fecho da certidão',confianca:'media'},
  {re:'[A-ZÀ-Ü][A-Za-zÀ-ÿ\\s.\'-]{2,40},\\s*(?:aos?\\s+)?(\\d{1,2}\\s+de\\s+[A-Za-zÀ-ÿ]+\\s+de\\s+\\d{1,2}\\.?\\d{3})',fonte:'data de fecho',confianca:'baixa',cauda:true},
];
const PESO={alta:3,media:2,baixa:1};
// A certidão nunca é anterior ao ato mais recente que ela própria certifica.
const tsUltimoAto=(dados.atos||[]).map(a=>{const p=parseData(a.data);return p?p.ts:0;}).reduce((x,y)=>Math.max(x,y),0);
const cauda=texto.slice(-2500);
const candidatos=[];
for(const p of PADROES){
  const alvo=p.cauda?cauda:texto;
  for(const m of alvo.matchAll(new RegExp(p.re,'gi'))){
    const dt=parseData(m[1]);
    if(!dt)continue;
    if(dt.ts>HOJE.getTime()+86400000)continue;  // data futura: não é expedição
    if(tsUltimoAto&&dt.ts<tsUltimoAto)continue; // anterior ao último ato: é data citada no corpo
    const antes=alvo.slice(Math.max(0,m.index-120),m.index);
    if(!p.semRuido&&RUIDO.test(antes))continue; // data de outro documento citado no ato
    // A hora vem logo após a data: "às 14:32:11" ou "18/12/2024 12:53:59".
    const fim=m.index+m[0].length;
    const posData=m[0].lastIndexOf(m[1]);
    const depois=m[0].slice(posData+m[1].length)+' '+alvo.slice(fim,fim+30);
    const hm=depois.match(/(?:[àa]s\s*)?\b(\d{1,2})[:h](\d{2})\b/);
    const ctx=alvo.slice(Math.max(0,m.index-40),fim+40).replace(/\s+/g,' ').trim();
    candidatos.push({...dt,prioridade:p.prioridade||2,fonte:p.fonte,confianca:p.confianca,hora:hm?String(hm[1]).padStart(2,'0')+':'+hm[2]:null,trecho:ctx.slice(0,180)});
  }
}
candidatos.sort((a,b)=>(a.prioridade-b.prioridade)||(PESO[b.confianca]-PESO[a.confianca])||(b.ts-a.ts));
const achada=candidatos[0]||null;
const VALIDADE_DIAS=30;
const dias_desde_emissao=achada?Math.floor((HOJE.getTime()-achada.ts)/86400000):null;
const certidao={
  detectada:!!achada,
  data:achada?achada.br:null,
  data_iso:achada?achada.iso:null,
  hora:achada?achada.hora:null,
  fonte:achada?achada.fonte:null,
  confianca:achada?achada.confianca:null,
  trecho:achada?achada.trecho:null,
  dias_desde_emissao,
  validade_dias:VALIDADE_DIAS,
  situacao:!achada?'nao_identificada':(dias_desde_emissao>VALIDADE_DIAS?'desatualizada':'atualizada'),
};

const documento={
  cabecalho:{titulo:'Análise de Matrícula',numero_matricula:dados.numero_matricula||null,cartorio:dados.cartorio||null,cartorio_curto:cartorio_curto||null,data_abertura:dados.data_abertura||null,data_certidao:certidao.data,certidao,livro_folha:dados.livro_folha||null,matricula_anterior:dados.matricula_anterior||null,sql_iptu:dados.sql_iptu||null,classificacao_risco,badge_risco_html:dados.badge_risco_html||''},
  imovel:{endereco:dados.endereco||null,endereco_curto:dados.endereco_curto||null,area_total_m2:dados.area_total_m2||null,area_total_display:fmtArea(dados.area_total_m2),area_construida_m2:dados.area_construida_m2||null,area_construida_display:fmtArea(dados.area_construida_m2),testada:dados.testada||null,confrontantes:dados.confrontantes||null,lat:dados.lat??null,lng:dados.lng??null,tem_onus,tem_onus_display:tem_onus?'Sim':'Não',ultimo_ato_tipo:dados.ultimo_ato_tipo||null},
  croqui:{svg:dados.croqui_svg||'',data_uri:dados.croqui_data_uri||'',precisao:dados.croqui_precisao||'N/D',disponivel:!!(dados.croqui_svg||dados.croqui_data_uri)},
  proprietarios:{lista:dados.proprietarios||[],html:dados.proprietarios_html||'',total:(dados.proprietarios||[]).length,origem:(dados.resumo_juridico&&dados.resumo_juridico.proprietarios_origem)||null,promissarios:{lista:dados.promissarios_cessionarios||[],html:dados.promissarios_html||'',total:(dados.promissarios_cessionarios||[]).length}},
  historico_atos:{lista:atos,total:atos.length},
  onus:{ativos:onus_ativos,total:onus_ativos.length},
  analise_juridica:{completa:analise,resumo,riscos_html:dados.riscos_html||'',inconsistencias_html:dados.inconsistencias_html||'',problemas_html:dados.problemas_html||'',onus_html:dados.onus_juridico_html||'',gravames_html:dados.gravames_juridico_html||'',cadeia_dominial_html:dados.cadeia_dominial_html||'',fundamentacao_html:dados.analise_fundamentacao_html||'',classes_juridicas_html:dados.analise_classes_juridicas_html||'',regras_html:dados.analise_regras_html||'',resumo_executivo:dados.analise_resumo_executivo||''},
  parecer:{texto:resumo.parecer_geral||'',html:dados.parecer_juridico_html||'',classificacao_risco,total_riscos:resumo.total_riscos??0},
  metadados:{data_extracao:new Date().toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}),total_paginas:dados.total_paginas??null,areas_destacadas:dados.areas_destacadas||[]}
};
return [{ json: { documento, dados } }];

// ─── VALIDAR DOCUMENTO ────────────────────────────────────────
const { documento, dados } = $input.first().json;
const erros=[],avisos=[];
if(!documento.cabecalho.numero_matricula)erros.push('Número da matrícula ausente.');
if(!documento.cabecalho.data_abertura)avisos.push('Data de abertura não identificada.');
// Data da certidão: nunca bloqueia o laudo — mas o leitor precisa saber quando
// ela não foi achada, quando veio de inferência fraca e quando já passou do
// prazo em que a certidão é aceita (30 dias).
const cert=documento.cabecalho.certidao||{detectada:false,situacao:'nao_identificada'};
if(!cert.detectada){
  avisos.push('Data de expedição da certidão não identificada no documento — confirme no original antes de usar o parecer.');
}else if(cert.situacao==='desatualizada'){
  avisos.push('Certidão expedida em '+cert.data+' (há '+cert.dias_desde_emissao+' dias, acima dos '+cert.validade_dias+' dias usuais): atos registrados depois dessa data não constam desta análise.');
}else if(cert.confianca==='baixa'){
  avisos.push('Data da certidão ('+cert.data+') inferida do fecho do documento, sem rótulo explícito de expedição — confira no original.');
}
for(const a of(dados.atos||[])){if(a.valor&&!/^\d{1,3}(\.\d{3})*,\d{2}$/.test(a.valor)){avisos.push('Valor fora do padrão em '+a.sequencia+': '+a.valor);}}
if((dados.areas_destacadas||[]).length&&documento.imovel.area_total_m2){avisos.push('Há destacamento de área registrado — confirme se a área total exibida está atualizada.');}
if(erros.length)throw new Error('Validação do documento falhou: '+erros.join(' | '));
documento.metadados.validacao={erros,avisos};
return [{ json: { documento, dados } }];

